-- GFT CANONICAL FAMILY IMPORT
-- PREPARED ONLY. Review before execution. No beneficiaries or finance data are included.
BEGIN;


-- Validation inside the transaction
DO $$ DECLARE c integer; bad integer; BEGIN SELECT COUNT(*) INTO c FROM family_people; IF c <> 224 THEN RAISE EXCEPTION 'Expected 224 family_people rows, found %',c; END IF; SELECT COUNT(*) INTO bad FROM family_people f WHERE f.parent_system_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM family_people p WHERE p.system_id=f.parent_system_id); IF bad <> 0 THEN RAISE EXCEPTION 'Found % family rows with missing parents',bad; END IF; IF EXISTS (SELECT 1 FROM family_people WHERE system_id='GFT-GEN4-182') THEN RAISE EXCEPTION 'Test registration GFT-GEN4-182 must not be imported'; END IF; END $$;
COMMIT;
